import json
from itertools import permutations

def solve_puzzle():
    # Input variables
    houses = [1, 2]  # Houses numbered from left (1) to right (2)
    names = ['Eric', 'Arnold']
    mothers = ['Aniya', 'Holly']
    cars = ['ford f150', 'tesla model 3']
    heights = ['short', 'very short']

    def house_of_value(mapping, value):
        for h, v in mapping.items():
            if v == value:
                return h
        return None

    solutions = []

    for name_perm in permutations(names):
        name_assign = {h: v for h, v in zip(houses, name_perm)}

        for mother_perm in permutations(mothers):
            mother_assign = {h: v for h, v in zip(houses, mother_perm)}

            # Clue 3: The person whose mother's name is Holly is in the second house.
            if mother_assign[2] != 'Holly':
                continue

            for car_perm in permutations(cars):
                car_assign = {h: v for h, v in zip(houses, car_perm)}

                # Clue 1: The person who owns a Tesla Model 3 is somewhere to the right of Arnold.
                house_tesla = house_of_value(car_assign, 'tesla model 3')
                house_arnold = house_of_value(name_assign, 'Arnold')
                if not (house_tesla is not None and house_arnold is not None and house_tesla > house_arnold):
                    continue

                for height_perm in permutations(heights):
                    height_assign = {h: v for h, v in zip(houses, height_perm)}

                    # Clue 2: Arnold is the person who is short.
                    if height_assign[house_arnold] != 'short':
                        continue

                    # All constraints satisfied; record solution
                    solution = {
                        'Name': name_assign.copy(),
                        'Mother': mother_assign.copy(),
                        'Car': car_assign.copy(),
                        'Height': height_assign.copy(),
                    }
                    solutions.append(solution)

    if not solutions:
        raise ValueError("No solution found.")

    # Assuming a unique solution
    sol = solutions[0]

    header = ["House", "Name", "Mother", "Car", "Height"]
    rows = []
    for h in sorted(houses):
        rows.append([
            str(h),
            sol['Name'][h],
            sol['Mother'][h],
            sol['Car'][h],
            sol['Height'][h]
        ])

    output = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }
    return output

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, indent=2))
